// Carrier2TestingStation 
// Retrieve or initialize context variables
let state = context.get("processState") || "idle"; // Our state machine
let lastDownstream = context.get("lastDownstream");
if (lastDownstream === undefined) {
    // Initially, x1B2 is True.
    lastDownstream = true;
    context.set("lastDownstream", lastDownstream);
}
let cycle1Start = context.get("cycle1Start") || null;  // Timestamp when x1B2 goes False
let cycle1Delta = context.get("cycle1Delta") || null;  // Delta for 1st cycle (x1B3 True - x1B2 False)
let cycle2Start = context.get("cycle2Start") || null;  // Timestamp when x1B3 goes False (after cycle1)
let cycleResults = context.get("cycleResults") || [];  // To store complete cycles

let topic = msg.topic;
let payload = msg.payload;

// --- State: idle ---
// Wait for x1B2 falling edge to start the 1st cycle
if (state === "idle") {
    if (topic === "x1B2") {
        // Check for falling edge: previously True and now False.
        if (lastDownstream === true && payload === false) {
            cycle1Start = new Date().getTime();
            context.set("cycle1Start", cycle1Start);
            context.set("processState", "waiting_sort1");
            node.warn("6_N_N Cycle 1 started : x1B3 false");
        }
        context.set("lastDownstream", payload);
    }
    return null;
}

// --- State: waiting_sort1 ---
// Wait for Sorting sensor (x1B3) to go True to complete the 1st cycle
else if (state === "waiting_sort1") {
    if (topic === "x1B3" && payload === true) {
        let cycle1End = new Date().getTime();
        cycle1Delta = cycle1End - cycle1Start;
        context.set("cycle1Delta", cycle1Delta);
        context.set("processState", "waiting_sort_false2");
        node.warn(+ cycle1Delta);
    }
    return null;
}

// --- State: waiting_sort_false2 ---
// After the 1st cycle, wait for the Sorting sensor (x1B3) to go False to mark the start of the 2nd cycle.
else if (state === "waiting_sort_false2") {
    if (topic === "x1B3" && payload === false) {
        cycle2Start = new Date().getTime();
        context.set("cycle2Start", cycle2Start);
        context.set("processState", "waiting_upstream2");
        node.warn("6_N_N Cycle 2 started : x1B3 false.");
    }
    return null;
}

// --- State: waiting_upstream2 ---
// Wait for Upstream sensor (x1B1) to go True to complete the 2nd cycle.
else if (state === "waiting_upstream2") {
    if (topic === "x1B1" && payload === true) {
        let cycle2End = new Date().getTime();
        let delta2 = cycle2End - cycle2Start;
        node.warn( + delta2);
        // Create two messages:
        // Message 1: 1st cycle data
        let msg1 = {
            topic: "Cycle 1",
            payload: { "6_N_N Timestamp Down str. to Sorting ": cycle1Delta }
        };
        // Message 2: 2nd cycle data
        let msg2 = {
            topic: "Cycle 2",
            payload: { "6_N_N Timestamp Sorting to Up str.": delta2 }
        };
        // Optionally, store the complete cycle
        cycleResults.push({ cycle1: cycle1Delta, cycle2: delta2 });
        context.set("cycleResults", cycleResults);
        // Reset state for the next complete cycle
        context.set("processState", "idle");
        context.set("cycle1Start", null);
        context.set("cycle1Delta", null);
        context.set("cycle2Start", null);

        // Return two messages: Output 1 for Cycle 1, Output 2 for Cycle 2.
        return [msg1, msg2];
    }
    return null;
}

// Fallback: reset if an unexpected state is encountered.
node.warn("Unexpected state: " + state);
context.set("processState", "idle");
return null;

// Get the current state of the process from the context
let processState = context.get("processState") || "idle"; // Possible states: "idle", "cylinderActive", "waitingAirSlide"
let startTime = context.get("startTime"); // Stores the start timestamp for the cycle

// Check if the input message contains the required properties
if (!msg.payload || !msg.topic) {
    return null;
}

// Extract the current topic and payload
let topic = msg.topic;
let payload = msg.payload;

// Handle "x1B1" (cylinder retracted)
if (topic === "x2M1") {
    if (payload === true) {
        // If the cylinder retracted signal is true and we're idle, start the cycle
        if (processState === "idle") {
            startTime = new Date().getTime(); // Record the current timestamp
            context.set("startTime", startTime);
            context.set("processState", "cylinderActive");
            node.warn("Cycle started: Cylinder retracted (x2M1)");
        }
    } else if (payload === false) {
        // Ignore false signals from "x1B1"
        return null;
    }
}

// Handle "x3M1" (Air slide)
else if (topic === "xB2") {
    if (payload === true) {
        // If the Air slide signal is true and we're waiting for it, complete the cycle
        if (processState === "cylinderActive") {
            let endTime = new Date().getTime(); // Record the current timestamp
            if (startTime) {
                let delta = Math.abs(endTime - startTime); // Calculate the time difference
                context.set("processState", "idle"); // Reset the state for the next cycle

                // Send the calculated delta as a new message
                return {
                    topic: "Cycle Time",
                    payload: delta
                };
            } else {
                node.error("Start time is missing. Cannot calculate delta.");
                return null;
            }
        }
    } else if (payload === false) {
        // Ignore false signals from "x3M1"
        return null;
    }
}

// Log unexpected topics
else {
    node.warn(`Unexpected topic "${topic}" received. Ignoring message.`);
    return null;
}

// Retrieve or initialize context variables for state and cycle timestamps
let state = context.get("processState") || "idle";  // Our state machine
let cycle1Start = context.get("cycle1Start") || null; // Timestamp when x1B1 falls (cycle 1 start)
let cycle1Delta = context.get("cycle1Delta") || null; // Delta for 1st cycle (x1B3 True - x1B1 False)
let cycle2Start = context.get("cycle2Start") || null; // Timestamp when x1B3 falls (cycle 2 start)
let cycleResults = context.get("cycleResults") || []; // To store complete cycles

// For reverse, track last state of Upstream (x1B1)
// Now we assume that initially, x1B1 is False.
let lastUpstream = context.get("lastUpstream");
if (lastUpstream === undefined) {
    lastUpstream = false;
    context.set("lastUpstream", lastUpstream);
}
// For the 2nd cycle, we assume Downstream (x1B2) initial state is False
let lastDownstream = context.get("lastDownstream");
if (lastDownstream === undefined) {
    lastDownstream = false;
    context.set("lastDownstream", lastDownstream);
}

let topic = msg.topic;
let payload = msg.payload;

// --- State: idle ---
// 1st cycle starts when Upstream sensor (x1B1) goes from True to False (falling edge).
if (state === "idle") {
    if (topic === "x1B1") {
        // Only trigger if the previous state was True and now it goes False.
        if (lastUpstream === true && payload === false) {
            cycle1Start = new Date().getTime();
            context.set("cycle1Start", cycle1Start);
            context.set("processState", "waiting_sort1");
            node.warn("6_N_N Reverse Cycle 3 started: x1B1 false.");
        }
        // Update lastUpstream state regardless.
        context.set("lastUpstream", payload);
    }
    return null;
}

// --- State: waiting_sort1 ---
// Wait for Sorting sensor (x1B3) to go True to complete the 1st cycle.
else if (state === "waiting_sort1") {
    if (topic === "x1B3" && payload === true) {
        let cycle1End = new Date().getTime();
        cycle1Delta = cycle1End - cycle1Start;
        context.set("cycle1Delta", cycle1Delta);
        // Move to next state: wait for Sorting sensor to go False (cycle 2 start).
        context.set("processState", "waiting_sort_false2");
        node.warn(+ cycle1Delta);
    }
    return null;
}

// --- State: waiting_sort_false2 ---
// After 1st cycle, wait for Sorting sensor (x1B3) to go False to mark the start of the 2nd cycle.
else if (state === "waiting_sort_false2") {
    if (topic === "x1B3" && payload === false) {
        cycle2Start = new Date().getTime();
        context.set("cycle2Start", cycle2Start);
        context.set("processState", "waiting_downstream2");
        node.warn("6_Y_Y Reverse Cycle 4 started : x1B3 false.");
    }
    return null;
}

// --- State: waiting_downstream2 ---
// Wait for Downstream sensor (x1B2) to go True to complete the 2nd cycle.
else if (state === "waiting_downstream2") {
    if (topic === "x1B2" && payload === true) {
        let cycle2End = new Date().getTime();
        let delta2 = cycle2End - cycle2Start;
        node.warn(+ delta2);
        // Prepare messages for both cycles.
        let msg1 = {
            topic: "Cycle 1",
            payload: { "6_N_N Timestamp Up str. to Sorting ": cycle1Delta }
        };
        let msg2 = {
            topic: "Cycle 2",
            payload: { "6_N_N Timestamp Sorting to Down str. ": delta2 }
        };
        cycleResults.push({ cycle1: cycle1Delta, cycle2: delta2 });
        context.set("cycleResults", cycleResults);
        // Reset state for the next complete reverse cycle.
        context.set("processState", "idle");
        context.set("cycle1Start", null);
        context.set("cycle1Delta", null);
        context.set("cycle2Start", null);
        return [msg1, msg2];
    }
    return null;
}

// Fallback: if an unexpected state is encountered, reset.
node.warn("Unexpected state: " + state);
context.set("processState", "idle");
return null;

